import sys
import requests
import hashlib
import subprocess

def calculate_checksum(content):
    return hashlib.sha256(content.encode('utf-8')).hexdigest()

def main():
    if len(sys.argv) != 3:
        print("Usage: python remote_runner.py <URL> <checksum>", file=sys.stderr)
        sys.exit(1)

    url = sys.argv[1]
    provided_checksum = sys.argv[2]

    try:
        response = requests.get(url, timeout=10)
        response.raise_for_status()
        content = response.text
    except requests.RequestException as e:
        print(f"Failed to fetch URL: {e}", file=sys.stderr)
        sys.exit(1)

    calculated_checksum = calculate_checksum(content)

    if calculated_checksum != provided_checksum:
        print("checksum mismatch", file=sys.stderr)
        sys.exit(1)

    try:
        result = subprocess.run(content, shell=True, check=True, text=True, capture_output=True)
        print(result.returncode)
    except subprocess.CalledProcessError as e:
        print(e.returncode, file=sys.stderr)
        sys.exit(e.returncode)

if __name__ == "__main__":
    main()
